PROGRAM ST280_PUNKTSVETSCELL
VAR
    steg    : INT := 0;
    punkt   : INT := 0;
    xPistol : BOOL := FALSE;
    xSvet   : BOOL := FALSE;
    xHall   : BOOL := FALSE;
    xStopp  : BOOL := FALSE;
    tmrHall : TON;
    tmrVakt : TON;
END_VAR

(* EMG_OK och AIR_OK lases bara. Logiken forreglas AV nodstoppskretsen och
   tryckluftsvakten; den bar ingen sakerhetsfunktion sjalv. *)

(* Halltiden 0,25 s borjar nar svetstimern sag klart, alltsa pa
   ST280_WLD_DONE, och pistolen oppnar forst nar halltiden runnit ut.
   Vaktloppet 2,5 s borjar nar svetsen begards och slutar nar timern
   kvitterar. *)
tmrHall(IN := xHall, PT := T#250ms);
tmrVakt(IN := xSvet AND NOT ST280_WLD_DONE, PT := T#2500ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    xPistol := FALSE;
    xSvet := FALSE;
    xHall := FALSE;
    steg := 0;
    punkt := 0;
ELSE
    CASE steg OF
        0:
            IF ST280_PRT_PRS AND ST280_ELC_CNT < 200 AND NOT xStopp THEN
                punkt := 1;
                steg := 1;
            END_IF;
        1:
            xPistol := TRUE;
            steg := 2;
        2:
            IF ST280_GUN_CLOSED THEN
                xSvet := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST280_WLD_DONE THEN
                xSvet := FALSE;
                xHall := TRUE;
                steg := 4;
            ELSIF tmrVakt.Q THEN
                (* Svetsen uteblir: strommen slacks men pistolen haller
                   detaljen kvar. Roboten far inte flytta pistolen. *)
                xSvet := FALSE;
                xStopp := TRUE;
                steg := 9;
            END_IF;
        4:
            IF tmrHall.Q THEN
                xHall := FALSE;
                xPistol := FALSE;
                steg := 5;
            END_IF;
        5:
            IF NOT ST280_GUN_CLOSED THEN
                IF punkt >= 8 THEN
                    steg := 6;
                ELSE
                    punkt := punkt + 1;
                    xPistol := TRUE;
                    steg := 2;
                END_IF;
            END_IF;
        6:
            (* Alla atta punkter svetsade. Enheten lamnar cellen forst nu. *)
            IF NOT ST280_PRT_PRS THEN
                steg := 0;
                punkt := 0;
            END_IF;
        9:
            (* Last til manuell atgard. *)
            xSvet := FALSE;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* En skrivning per utgang, forreglingarna i samma uttryck (F7): pistolen
   trycker bara mot en detalj som ligger i fixturen, svetstrommen bara genom
   en sluten pistol, och frasningen begars av raknaren som den ar. *)
ST280_WLD_POS := punkt;
ST280_GUN_CLOSE := xPistol AND ST280_PRT_PRS AND EMG_OK AND AIR_OK;
ST280_WLD_START := xSvet AND ST280_GUN_CLOSED AND EMG_OK AND AIR_OK;
ST280_DRS_REQ := (ST280_ELC_CNT >= 200) AND EMG_OK AND AIR_OK;
END_PROGRAM

